// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

abstract contract ReentrancyGuard {
    error ReentrantCall();

    uint256 private _guard = 1;

    modifier nonReentrant() {
        if (_guard != 1) revert ReentrantCall();
        _guard = 2;
        _;
        _guard = 1;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import { IERC20 } from "../interfaces/IERC20.sol";

library SafeERC20 {
    error ERC20CallFailed();

    function safeTransfer(IERC20 token, address to, uint256 amount) internal {
        _call(token, abi.encodeCall(IERC20.transfer, (to, amount)));
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 amount) internal {
        _call(token, abi.encodeCall(IERC20.transferFrom, (from, to, amount)));
    }

    function _call(IERC20 token, bytes memory data) private {
        (bool success, bytes memory result) = address(token).call(data);
        if (!success || (result.length != 0 && !abi.decode(result, (bool)))) {
            revert ERC20CallFailed();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

interface IArcBaseRegistrar {
    function baseNode() external view returns (bytes32);
    function gracePeriod() external view returns (uint256);
    function nameExpires(uint256 id) external view returns (uint256);
    function available(uint256 id) external view returns (bool);
    function isActive(uint256 id) external view returns (bool);
    function ownerOf(uint256 id) external view returns (address);
    function getApproved(uint256 id) external view returns (address);
    function isApprovedForAll(address owner, address operator) external view returns (bool);

    function register(
        uint256 id,
        address owner,
        uint256 duration,
        address resolver,
        bytes[] calldata resolverData
    ) external returns (uint256 expires);
    function renew(uint256 id, uint256 duration) external returns (uint256 expires);
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

